


export type ExpandedPackageSummary = { "carrier"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "delivered_at"?: string; "fulfillment_id": string; "package_id": string; "service_code"?: string; "shipment_id": string; /** RFC3339 timestamp. Format: date-time. */ "shipped_at"?: string; /** Current package lifecycle state. - `created`: The package record exists but has not been packed or handed off. - `packed`: The package is packed and awaiting carrier handoff. - `shipped`: The package was handed to the carrier. - `in_transit`: The carrier is moving the package through its network. - `out_for_delivery`: The package is on its final delivery route. - `delivered`: The carrier reported successful delivery. - `delivery_attempted`: The carrier attempted delivery but did not complete it. Follow the carrier instructions before retrying delivery. - `exception`: A carrier exception is blocking normal progress. Resolve the carrier-reported issue. - `returned`: The package was returned toward or to its origin. - `voided`: The package was voided and will not continue through delivery. */ "status": "created" | "packed" | "shipped" | "in_transit" | "out_for_delivery" | "delivered" | "delivery_attempted" | "exception" | "returned" | "voided" | (string & {}); /** Read-only actions currently supported for this package. */ "supported_actions": Array<"mark_delivered" | "mark_delivery_attempted" | "mark_exception" | "mark_in_transit" | "mark_out_for_delivery" | "mark_packed" | "mark_returned" | "mark_shipped" | (string & {})>; "tracking_number"?: string; "tracking_url"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** Monotonic package version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; };
